import{_ as a,o as e,c as r,al as o}from"./chunks/framework.BawR2jEz.js";const u=JSON.parse('{"title":"Рубрика «Страница OpenCart»","description":"Переопределение стандартных шаблонов OpenCart на кастомные Twig-шаблоны exDoc через рубрику страницы.","frontmatter":{"title":"Рубрика «Страница OpenCart»","description":"Переопределение стандартных шаблонов OpenCart на кастомные Twig-шаблоны exDoc через рубрику страницы."},"headers":[],"relativePath":"rubrics/oc-page/index.md","filePath":"rubrics/oc-page/index.md"}'),d={name:"rubrics/oc-page/index.md"};function c(n,t,h,i,l,p){return e(),r("div",null,[...t[0]||(t[0]=[o('<div><h1 id="рубрика-«страница-opencart»" tabindex="-1">Рубрика «Страница OpenCart» <a class="header-anchor" href="#рубрика-«страница-opencart»" aria-label="Permalink to &quot;Рубрика «Страница OpenCart»&quot;">​</a></h1><p>Тип: <code>rub_oc_page</code></p><p>Рубрика страницы OpenCart позволяет переопределить стандартные шаблоны OpenCart на кастомные Twig-шаблоны exDoc. При привязке рубрики к маршруту exDoc перехватывает рендеринг страницы и использует шаблон рубрики вместо стандартного.</p><h2 id="настроики" tabindex="-1">Настройки <a class="header-anchor" href="#настроики" aria-label="Permalink to &quot;Настройки&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Параметр</th><th>Описание</th></tr></thead><tbody><tr><td><strong>Название</strong></td><td>Имя рубрики (например, «Страница товара», «Каталог»)</td></tr><tr><td><strong>Хэштег</strong></td><td>Уникальный идентификатор</td></tr><tr><td><strong>Маршрут (route)</strong></td><td>Маршрут OpenCart, который переопределяет рубрика</td></tr><tr><td><strong>Шаблон-обёртка</strong></td><td>Header/footer — каркас страницы</td></tr><tr><td><strong>Статус</strong></td><td>Включена/выключена</td></tr></tbody></table><h3 id="доступные-маршруты" tabindex="-1">Доступные маршруты <a class="header-anchor" href="#доступные-маршруты" aria-label="Permalink to &quot;Доступные маршруты&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Маршрут</th><th>Страница</th><th>Объект контекста</th></tr></thead><tbody><tr><td><code>product/product</code></td><td>Страница товара</td><td><a href="./product-context.html">Товар OpenCart</a></td></tr><tr><td><code>product/category</code></td><td>Страница категории товаров</td><td><a href="./oc-category-context.html">Категория OpenCart</a></td></tr><tr><td><code>product/manufacturer_info</code></td><td>Страница производителя</td><td><a href="./manufacturer-context.html">Производитель OpenCart</a></td></tr></tbody></table><p>В зависимости от маршрута, в шаблон передаётся соответствующий объект контекста со свойствами и методами сущности OpenCart.</p><p><strong>Остальные маршруты.</strong> Рубрику можно привязать к любой странице магазина — главной, поиску, входу в личный кабинет, странице ошибки. Список доступных маршрутов предлагает подсказка в поле «Маршрут». Собственного объекта контекста у таких страниц нет: свойств сущности в шаблоне не будет, а <code>fld()</code> вернёт поле, заведённое на самой рубрике — одно и то же для всех посетителей страницы.</p><h2 id="разделы-формы" tabindex="-1">Разделы формы <a class="header-anchor" href="#разделы-формы" aria-label="Permalink to &quot;Разделы формы&quot;">​</a></h2><h3 id="поля-рубрики" tabindex="-1">Поля рубрики <a class="header-anchor" href="#поля-рубрики" aria-label="Permalink to &quot;Поля рубрики&quot;">​</a></h3><p>Определение дополнительных полей для сущности OpenCart. Эти поля расширяют стандартные данные OC — например, можно добавить поле «Видеообзор» к товару, которого нет в стандартном OpenCart. Подробнее см. <a href="/exdoc-docs/fields/">Поля</a>.</p><h3 id="макет-страницы" tabindex="-1">Макет страницы <a class="header-anchor" href="#макет-страницы" aria-label="Permalink to &quot;Макет страницы&quot;">​</a></h3><p>Twig-шаблон страницы. Используется <a href="/exdoc-docs/editor/">Редактор</a> с вкладками: шаблон, стили (SCSS), JavaScript, подключение ссылок, язык. Внутри шаблона доступен объект контекста с данными сущности OpenCart и методами exDoc (<code>fld()</code>, <code>getMainImage()</code>, <code>getManufacturer()</code> и др.).</p><h3 id="макеты-полеи" tabindex="-1">Макеты полей <a class="header-anchor" href="#макеты-полеи" aria-label="Permalink to &quot;Макеты полей&quot;">​</a></h3><p>Twig-шаблоны для каждого поля рубрики. Определяют, как отдельное поле рендерится на фронте.</p><h3 id="макеты-превью" tabindex="-1">Макеты превью <a class="header-anchor" href="#макеты-превью" aria-label="Permalink to &quot;Макеты превью&quot;">​</a></h3><p>Шаблоны миниатюр для отображения сущностей в списках. Каждый thumb — со своим шаблоном, стилями и скриптами. Вызываются через <code>ex.rubric_thumb()</code>.</p><h3 id="компоненты" tabindex="-1">Компоненты <a class="header-anchor" href="#компоненты" aria-label="Permalink to &quot;Компоненты&quot;">​</a></h3><p>Переиспользуемые Twig-фрагменты, доступные через <code>{{ component(&#39;hashtag&#39;) }}</code>.</p><h2 id="привязка-к-конкретным-сущностям" tabindex="-1">Привязка к конкретным сущностям <a class="header-anchor" href="#привязка-к-конкретным-сущностям" aria-label="Permalink to &quot;Привязка к конкретным сущностям&quot;">​</a></h2><p>Рубрика <code>rub_oc_page</code> может быть привязана глобально (ко всем товарам/категориям) или к конкретным сущностям (например, к определённой категории товаров). Это позволяет использовать разные шаблоны для разных разделов каталога.</p><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="./product-context.html">Объект товара</a> — свойства и методы в шаблоне товара</li><li><a href="./oc-category-context.html">Объект категории OpenCart</a> — свойства и методы в шаблоне категории</li><li><a href="./manufacturer-context.html">Объект производителя</a> — свойства и методы в шаблоне производителя</li><li><a href="/exdoc-docs/fields/">Поля</a> — типы полей</li></ul></div>',1)])])}const b=a(d,[["render",c]]);export{u as __pageData,b as default};
